export function homepageSectionRewrite(file, source) {
  for (const [before, after] of HOMEPAGE_SECTION_EDITS[file] ?? []) {
    if (!source.includes(before)) throw new Error(`Homepage adaptation drift: ${file}`);
    source = source.replace(before, after);
  }
  return source;
}
